function refundIdempotencyKey(ref,body){var fingerprint=ref+'|'+JSON.stringify(body),storageKey='black-sheep-refund-pending';try{var saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(saved&&saved.fingerprint===fingerprint&&saved.key)return saved.key}catch(e){}var key=window.crypto&&typeof window.crypto.randomUUID==='function'?window.crypto.randomUUID():'refund-'+Date.now()+'-'+Math.random().toString(36).slice(2);try{sessionStorage.setItem(storageKey,JSON.stringify({fingerprint:fingerprint,key:key}))}catch(e){}return key}
