function renderLineChart(id,raw,days){var svg=document.getElementById(id);if(!svg)return;var data=fillDaily(raw,days),W=760,H=220,pad=28,max=Math.max.apply(null,data.map(function(d){return d.revenueMinor}).concat([100])),pts=data.map(function(d,i){var x=pad+(W-pad*2)*(data.length===1?0:i/(data.length-1)),y=H-pad-(H-pad*2)*(d.revenueMinor/max);return{x:x,y:y,d:d}}),grid='';for(var g=0;g<5;g++){var gy=pad+(H-pad*2)*g/4;grid+='<line class="chart-gridline" x1="'+pad+'" x2="'+(W-pad)+'" y1="'+gy+'" y2="'+gy+'"></line>'}var line=pts.map(function(p){return p.x.toFixed(1)+','+p.y.toFixed(1)}).join(' '),area=pad+','+(H-pad)+' '+line+' '+(W-pad)+','+(H-pad),dots=pts.filter(function(p,i){return data.length<15||i%Math.ceil(data.length/12)===0||i===data.length-1}).map(function(p){return '<circle class="chart-dot" cx="'+p.x+'" cy="'+p.y+'" r="3"></circle>'}).join(''),labels=pts.filter(function(p,i){return i===0||i===data.length-1||i===Math.floor(data.length/2)}).map(function(p){return '<text class="axis-label" x="'+p.x+'" y="'+(H-5)+'" text-anchor="middle">'+esc(formatDay(p.d.day))+'</text>'}).join('');svg.innerHTML=grid+'<polygon class="chart-area" points="'+area+'"></polygon><polyline class="chart-line" points="'+line+'"></polyline>'+dots+labels}
