document.getElementById('availabilityLoss').innerHTML=(r.availabilityLoss||[]).map(function(x){return '<tr><td><strong>'+esc(x.productName)+'</strong><div class="muted">'+Number(x.affectedOrders||0)+' affected orders</div></td><td>'+Number(x.requestedQuantity||0)+'</td><td>'+Number(x.confirmedQuantity||0)+'</td><td>'+money(x.lostValueMinor)+'</td></tr>'}).join('')||'<tr><td colspan="4" class="muted">No availability losses recorded.</td></tr>';
